VALUES
    ((SELECT id FROM batch_sets WHERE set_code = 'pref-ranking-1'), '001-gyoza-spend', 'top5-map', 'ぎょうざ大好き都道府県',
     '{"hook":"宇都宮か、浜松か。…どっちでもないんだなこれが！","trivia":"浜松市は単体だと4,051円で全国トップ級だ！でも静岡市と合わせた県の平均だと3位に落ち着くんだな。宇都宮をかかえる栃木は2位。3年平均で王座に立ったのは、なんと宮崎県だったぞ！","source_display":"総務省 家計調査 2023〜25年平均／二人以上世帯の年間支出（政令市等を世帯数加重で県換算）","result_list":"1位 宮崎県 3,478円\\n2位 栃木県 3,192円\\n3位 静岡県 3,091円\\n4位 滋賀県 2,455円\\n5位 埼玉県 2,412円","value_prefix":"年間","value_suffix":"円","subtitle":"全国平均は1,984円","bg_motif":"焼き上がった餃子と立ちのぼる湯気、屋台ののれんと提灯をやわらかく配した和のモチーフ"}', '{"entries":[{"rank":1,"pref_code":45,"value":3478},{"rank":2,"pref_code":9,"value":3192},{"rank":3,"pref_code":22,"value":3091},{"rank":4,"pref_code":25,"value":2455},{"rank":5,"pref_code":11,"value":2412}]}', '{"20s":{"intro":"ぎょうざ大好き都道府県！","teaser":"みんなはどこだと思う？","r5":"まずは5位、埼玉県！","r4":"つぎは4位、滋賀県！","r3":"3位は、静岡県！","r2":"惜しくも2位、栃木県！","r1_call":"さあ、栄えある1位は！","r1_name":"宮崎県ーっ！","outro":"みんなはわかったかな？"},"30s":{"intro":"ぎょうざ大好き都道府県、トップ5！","teaser":"1位はどこだと思う？","r5":"第5位は、埼玉県！","r5_comment":"関東から来た！","r4":"第4位は、滋賀県！","r4_comment":"まさかの近江！","r3":"第3位は、静岡県！","r3_comment":"浜松の力だ！","r2":"第2位は、栃木県！","r2_comment":"本場の意地！","r1_call":"さあ第1位、ぎょうざ王は！","r1_name":"宮崎県ーっ！","closing":"宇都宮と浜松をおさえて、宮崎が王座だ！"}}', '出典: 総務省統計局「家計調査 品目別都道府県庁所在市及び政令指定都市ランキング」 / データ年: 2023年（令和５年）～2025年（令和７年）平均 / 取得日: 2026-08-10 / URL: https://www.stat.go.jp/data/kakei/zuhyou/rank10.xlsx
