    ((SELECT id FROM batch_sets WHERE set_code = 'pref-ranking-1'), '009-onsen-sources', 'top5-map', '温泉の源泉が多い県',
     '{"hook":"全国27,899本の源泉。その5本に1本近くが、この県にあるんだぞ！","trivia":"1位の大分県は5,094本！全国27,899本のおよそ18%が大分に集中してるぞ。2位の鹿児島県2,735本、3位の北海道2,249本と続いて、九州勢が上位に2県だ。源泉総数は利用中と未利用を合わせた本数だな！","source_display":"環境省 令和6年度 温泉利用状況（令和7年3月末現在）","result_list":"1位 大分県 5,094本\\n2位 鹿児島県 2,735本\\n3位 北海道 2,249本\\n4位 静岡県 2,185本\\n5位 熊本県 1,339本","value_prefix":null,"value_suffix":"本","subtitle":"全国の源泉は27,899本","bg_motif":"湯けむりの立つ露天風呂と手ぬぐい、湯の花と石畳をあしらった落ち着いた和のモチーフ"}', '{"entries":[{"rank":1,"pref_code":44,"value":5094},{"rank":2,"pref_code":46,"value":2735},{"rank":3,"pref_code":1,"value":2249},{"rank":4,"pref_code":22,"value":2185},{"rank":5,"pref_code":43,"value":1339}]}', '{"20s":{"intro":"温泉の源泉が多い県！","teaser":"みんなはどこだと思う？","r5":"まずは5位、熊本県！","r4":"つぎは4位、静岡県！","r3":"3位は、北海道！","r2":"2位は、鹿児島県！","r1_call":"さあ、栄えある1位は！","r1_name":"大分県ーっ！","outro":"みんなはわかったかな？"},"30s":{"intro":"温泉の源泉が多い県、トップ5！","teaser":"1位はどこだと思う？","r5":"第5位は、熊本県！","r5_comment":"阿蘇の恵みだ！","r4":"第4位は、静岡県！","r4_comment":"伊豆と熱海！","r3":"第3位は、北海道！","r3_comment":"広さがすごい！","r2":"第2位は、鹿児島県！","r2_comment":"火山のちから！","r1_call":"さあ第1位、温泉王国は！","r1_name":"大分県ーっ！","closing":"全国の源泉の、およそ2割が大分にあるんだ！"}}', '出典: 環境省「令和6年度温泉利用状況」 / データ年: 令和6年度（令和7年3月末現在） / 取得日: 2026-08-10 / URL: https://www.env.go.jp/nature/onsen/pdf/6-7_p_1.pdf
